Mesh<RT::Bare_point, double> power_diagram_faces(RT const &rt, double threshold) {
    Mesh<RT::Bare_point, double> mesh;

    // Collect all vertices
    std::vector<RT::Bare_point> vertices;
    for (RT::Finite_vertices_iterator vertex = rt.finite_vertices_begin();
         vertex != rt.finite_vertices_end(); ++vertex) {
        vertices.push_back(vertex->point());
    }
    mesh.vertices = vertices;

    // Process edges
    for (RT::Finite_edges_iterator edge = rt.finite_edges_begin();
         edge != rt.finite_edges_end(); ++edge) {

        // Calculate edge length
        double edge_length = CGAL::to_double(edge->first->vertex(0)->point() -
                                           edge->second->vertex(0)->point()).norm();

        if (edge_length < threshold) {
            continue;
        }

        // Get the two incident cells
        RT::Cell_handle cell1 = edge->first;
        RT::Cell_handle cell2 = edge->second;

        // Process cell1
        for (int i = 0; i < 4; ++i) {
            std::vector<unsigned> face_vertices;
            for (int j = 0; j < 3; ++j) {
                face_vertices.push_back(j);
            }
            mesh.push_back(face_vertices, edge_length);
